mapper.select:
/* MenuFavoriteMapper."selectFavoriteMenuDIds" */
SELECT
	MENU_D_ID
FROM TB_USER_MENU_FAVORITE
WHERE 1=1
  AND CMPNY_CD = #{cmpnyCd}
  AND USER_CD = #{userCd}
ORDER BY INSERT_DATE, MENU_D_ID

/* MenuFavoriteMapper."countFavorite" */
SELECT COUNT(*)
FROM TB_USER_MENU_FAVORITE
WHERE 1=1
  AND CMPNY_CD = #{cmpnyCd}
  AND USER_CD = #{userCd}
  AND MENU_D_ID = #{menuDId}

mapper.insert:
/* MenuFavoriteMapper."insertFavorite" */
INSERT INTO TB_USER_MENU_FAVORITE (
	CMPNY_CD
	, USER_CD
	, MENU_D_ID
	, INSERT_NO
	, INSERT_DATE
)
VALUES (
	#{cmpnyCd}
	, #{userCd}
	, #{menuDId}
	, #{userCd}
	, NOW()
)

mapper.delete:
/* MenuFavoriteMapper."deleteFavorite" */
DELETE FROM TB_USER_MENU_FAVORITE
WHERE 1=1
  AND CMPNY_CD = #{cmpnyCd}
  AND USER_CD = #{userCd}
  AND MENU_D_ID = #{menuDId}
